import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Auth And Security Operations","description":"","frontmatter":{"title":"Auth And Security Operations"},"headers":[],"relativePath":"operations/auth-and-security-operations.md","filePath":"operations/auth-and-security-operations.md","lastUpdated":1787839527000}'),i={name:"operations/auth-and-security-operations.md"};function n(l,e,d,h,s,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="auth-and-security-operations" tabindex="-1">Auth-And-Security-Operations <a class="header-anchor" href="#auth-and-security-operations" aria-label="Permalink to &quot;Auth-And-Security-Operations&quot;">​</a></h1><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>整理後端登入/權限整合的「操作型」規格與安全政策，避免在 debug/部署時因憑證/secret 誤用造成安全風險或不可用。</p><h2 id="登入架構-google-email-refresh-rotation" tabindex="-1">登入架構（Google / Email / Refresh rotation） <a class="header-anchor" href="#登入架構-google-email-refresh-rotation" aria-label="Permalink to &quot;登入架構（Google / Email / Refresh rotation）&quot;">​</a></h2><ul><li>主方案：<a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/docs/google-backend-auth.md" target="_blank" rel="noreferrer"><code>docs/google-backend-auth.md</code></a></li></ul><p>後端主要端點（運維/串接用）：</p><ul><li><code>POST /api/auth/google/prepare</code>：取得一次性 nonce（目的：login/link）</li><li><code>POST /api/auth/google</code>：用 Google idToken 完成登入/連結並回傳本地 Bearer token + refresh token</li><li><code>POST /api/auth/refresh</code>：refresh token rotation（舊 token 被替換）</li><li><code>POST /api/auth/logout</code>：撤銷 refresh token family</li><li><code>GET /api/auth/me</code>：回傳目前登入者 profile / 權限資訊</li></ul><h2 id="token-與風險控管-和安全策略一致" tabindex="-1">Token 與風險控管（和安全策略一致） <a class="header-anchor" href="#token-與風險控管-和安全策略一致" aria-label="Permalink to &quot;Token 與風險控管（和安全策略一致）&quot;">​</a></h2><ul><li>使用短效 Bearer access token</li><li>refresh token reuse 偵測：重複使用舊 token 會撤銷整個 token family</li><li>refresh token 只存 hash，不存明文（避免資料庫外洩造成可用 token 泄漏）</li></ul><h2 id="drive-oauth-405-refresh" tabindex="-1">Drive OAuth／405／refresh <a class="header-anchor" href="#drive-oauth-405-refresh" aria-label="Permalink to &quot;Drive OAuth／405／refresh&quot;">​</a></h2><p>Google 備份、server auth code、refresh token 類問題要同時查前端 auth flow 與後端 <code>/api/google/oauth/*</code> host，不要只修 UI 登入。細節：<a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/docs/google-backend-auth.md" target="_blank" rel="noreferrer"><code>docs/google-backend-auth.md</code></a>。Cookie session 只負責 restore；呼叫 API 仍要 access token。</p><h2 id="安全政策-必讀" tabindex="-1">安全政策（必讀） <a class="header-anchor" href="#安全政策-必讀" aria-label="Permalink to &quot;安全政策（必讀）&quot;">​</a></h2><p>主要規範：</p><ul><li>不提交 secret/密鑰檔（Wiki 只描述用途/必填/行為）</li><li>安全漏洞走私下回報（依 SECURITY.md）</li></ul><h2 id="引用來源" tabindex="-1">引用來源 <a class="header-anchor" href="#引用來源" aria-label="Permalink to &quot;引用來源&quot;">​</a></h2><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/docs/google-backend-auth.md" target="_blank" rel="noreferrer"><code>docs/google-backend-auth.md</code></a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/SECURITY.md" target="_blank" rel="noreferrer"><code>SECURITY.md</code></a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a></li></ul>',16)])])}const k=o(i,[["render",n]]);export{p as __pageData,k as default};
